import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.CAXxHpAX.js";const m=JSON.parse('{"title":"Theengs BLE MQTT gateway","description":"","frontmatter":{"title":"Theengs BLE MQTT gateway"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1778435235000}'),n={name:"index.md"};function s(i,e,l,h,g,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="theengs-ble-mqtt-gateway" tabindex="-1">Theengs BLE MQTT gateway <a class="header-anchor" href="#theengs-ble-mqtt-gateway" aria-label="Permalink to &quot;Theengs BLE MQTT gateway&quot;">​</a></h1><p><strong>Theengs Gateway</strong> is a multi-platform, multi devices Bluetooth Low Energy (BLE) to MQTT gateway that leverages the <a href="https://github.com/theengs/decoder" target="_blank" rel="noreferrer">Theengs Decoder library</a>. It retrieves data from a wide range of <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">BLE sensors</a>, including the LYWSD03MMC, CGD1, CGP1W, H5072, H5075, H5102, TH1, TH2, CGH1, CGDK2, CGPR1, RuuviTag, WS02, WS08, TPMS, MiScale, LYWSD02, LYWSDCGQ, and MiFlora, and translates this information into a readable JSON format and pushes those to an MQTT broker.</p><p>Enabling integration to Internet of Things (IoT) platforms or home automation controllers like <a href="https://nodered.org/" target="_blank" rel="noreferrer">NodeRED</a>, <a href="https://aws.amazon.com/iot/" target="_blank" rel="noreferrer">AWS IoT</a>, <a href="https://www.home-assistant.io/" target="_blank" rel="noreferrer">Home Assistant</a>, <a href="https://www.openhab.org/" target="_blank" rel="noreferrer">OpenHAB</a>, <a href="https://fhem.de/" target="_blank" rel="noreferrer">FHEM</a>, <a href="https://www.iobroker.net/" target="_blank" rel="noreferrer">ioBroker</a> or <a href="https://domoticz.com/" target="_blank" rel="noreferrer">Domoticz</a>.</p><p>The gateway uses the Bluetooth Low Energy adapter of your Raspberry Pi, Windows, Apple desktop, laptop, or server by leveraging Python and multi-platform libraries.</p><p><img src="https://github.com/theengs/home/raw/development/docs/img/Theengs-gateway-raspberry-pi.jpg" alt="Gateway"></p><p>You can use <strong>Theengs Gateway</strong> as a standalone solution or as a complementary solution to <a href="https://docs.openmqttgateway.com/" target="_blank" rel="noreferrer">OpenMQTTGateway</a>, as it uses the same MQTT topic structure and the same payload messages. Your OpenMQTTGateway home automation BLE sensors integration also works with Theengs Gateway.</p><p>The gateway retrieves data from BLE sensors from Govee, Xiaomi, Inkbird, Qingping, ThermoBeacon, Blue Maestro, and many more.</p>',7)])])}const T=t(n,[["render",s]]);export{m as __pageData,T as default};
